// Valider les parametres requis
const input = $input.first().json;
const body = input.body || input;

const projectId = body.project_id || null;
const discordUserId = body.discord_user_id || null;

const errors = [];
if (!projectId) errors.push('project_id');
if (!discordUserId) errors.push('discord_user_id');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Parametres requis manquants: ${errors.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    project_id: projectId,
    discord_user_id: discordUserId,
    redis_key: `project:${projectId}`
  }
}];

// Extraire le stripe_customer_id de la reponse API
const apiResponse = $input.first().json;
const inputData = $('Validate Input').first().json;

const statusCode = apiResponse.statusCode || 200;
const body = apiResponse.body || apiResponse;

// Verifier si l'utilisateur existe
if (statusCode === 404 || !body || body.error) {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: 'Utilisateur non trouve. Vous devez d\'abord souscrire a un plan.',
        status: 'NOT_FOUND'
      }
    }
  }];
}

// Verifier si l'utilisateur a un stripe_customer_id
const stripeCustomerId = body.stripe_customer_id;

if (!stripeCustomerId) {
  return [{
    json: {
      found: false,
      error: {
        code: 400,
        message: 'Aucun abonnement Stripe trouve. Utilisez /subscribe pour souscrire.',
        status: 'NO_SUBSCRIPTION'
      }
    }
  }];
}

return [{
  json: {
    found: true,
    project_id: inputData.project_id,
    discord_user_id: inputData.discord_user_id,
    stripe_customer_id: stripeCustomerId,
    redis_key: inputData.redis_key
  }
}];

// Verifier que le projet existe dans Redis et extraire stripe_key
const redisResult = $('Get Stripe Config (Redis)').first();
const inputData = $('Check Subscriber').first().json;

// Verifier si Redis a retourne une erreur
const redisJson = redisResult?.json || {};
if (redisJson.error || redisJson.message?.includes('ECONNREFUSED')) {
  return [{
    json: {
      found: false,
      error: {
        code: 503,
        message: 'Service Redis indisponible',
        status: 'SERVICE_UNAVAILABLE'
      }
    }
  }];
}

// Redis retourne la valeur dans propertyName, value, ou directement
const rawValue = redisJson.propertyName || redisJson.value || redisJson;

if (!rawValue || rawValue === null || rawValue === 'null') {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Projet '${inputData.project_id}' non enregistre.`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

// Parser le JSON stocke dans Redis
let project;
try {
  project = typeof rawValue === 'string' ? JSON.parse(rawValue) : rawValue;
} catch (e) {
  return [{
    json: {
      found: false,
      error: {
        code: 500,
        message: `Erreur parsing Redis: ${e.message}`,
        status: 'INTERNAL_ERROR'
      }
    }
  }];
}

if (!project.stripe_key) {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Projet '${inputData.project_id}' n'a pas de cle Stripe configuree`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

return [{
  json: {
    found: true,
    project_id: inputData.project_id,
    discord_user_id: inputData.discord_user_id,
    stripe_customer_id: inputData.stripe_customer_id,
    stripe_key: project.stripe_key,
    return_url: `${$env.STRIPE_WEBHOOK_URL}/webhook/${inputData.project_id}/subscription/portal`
  }
}];

// Formater la reponse Stripe Billing Portal
const input = $input.first().json;
const projectData = $('Check Project').first().json;

const statusCode = input.statusCode || 200;
const data = input.body || input;

// Verifier les erreurs Stripe
if (statusCode >= 400 || data.error) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || 'Erreur Stripe Billing Portal',
        status: 'STRIPE_ERROR',
        type: data.error?.type || 'api_error'
      }
    }
  }];
}

return [{
  json: {
    success: true,
    portal_url: data.url,
    return_url: projectData.return_url,
    project_id: projectData.project_id,
    discord_user_id: projectData.discord_user_id,
    expires_at: new Date(data.created * 1000 + 300000).toISOString() // 5 min expiry
  }
}];
